<template>
  <div class="vote_list_box">
    <el-container>
      <el-header>

        <el-row>
          <el-col :span="4">
            <el-button type="primary" icon="el-icon-plus" @click="add_template">添加模板</el-button>
          </el-col>
          <el-col :span="20">
            <span>筛选：</span>
            <el-input class="search_width" v-model="search_val" size="small" maxlength="10" placeholder="请输入搜索内容"></el-input>
            <el-select class="search_width" v-model="search_type" placeholder="请选择" size="small">
              <el-option
                v-for="item in options"
                :key="item.value"
                :label="item.label"
                :value="item.value">
              </el-option>
            </el-select>
            &nbsp;&nbsp;&nbsp;&nbsp;
            <span>日期筛选：</span>
            <el-date-picker
              size="small"
              v-model="date"
              value-format="yyyy/MM/dd"
              type="daterange"
              range-separator="至"
              start-placeholder="开始日期"
              end-placeholder="结束日期">
            </el-date-picker>
            &nbsp;&nbsp;&nbsp;&nbsp;
            <el-button type="primary" icon="el-icon-search" @click="search_list">查询</el-button>
          </el-col>
        </el-row>

      </el-header>
      <el-main class="table_box" v-if="template_data">
        <el-table
          class="list_table"
          :data="template_data"
          style="width:100%"
          :row-class-name="tableRowClassName"
          :height="550">
          <!-- <el-table-column
            prop="template_id"
            label="ID"
            min-width="40">
          </el-table-column> -->
           <el-table-column
            label="ID"
            min-width="40">
            <template slot-scope="scope">
              <el-row v-if="scope.row.from=='default'">
                <el-col :span="24">默认</el-col>
              </el-row>
              <el-row v-else>
                <el-col :span="24">{{scope.row.template_id}}</el-col>
              </el-row>
            </template>
          </el-table-column>
          <el-table-column
            prop="template_title"
            label="模板标题"
            min-width="120">
          </el-table-column>
           <el-table-column
            label="添加时间"
            min-width="150">
            <template slot-scope="scope">
              <el-row v-if="scope.row.from=='default'">
                <el-col :span="24">系统默认添加</el-col>
              </el-row>
              <el-row v-else>
                <el-col :span="24">{{scope.row.add_time_txt}}</el-col>
              </el-row>
            </template>
          </el-table-column>
          <el-table-column
            label="二维码"
            min-width="50">
            <template slot-scope="scope">
              <el-button v-if="scope.row.from!='default' && scope.row.qrcode_url!=''" type="text" size="small" @click.native.prevent="look_qrcode(scope.$index, template_data)">查看二维码</el-button>
            </template>
          </el-table-column>
          <el-table-column
            fixed="right"
            label="操作"
            width="300">
            <template slot-scope="scope">
              <el-button v-if="scope.row.from!='default'" type="text" size="small" @click.native.prevent="template_title_write(scope.$index, template_data)">标题填写</el-button>
              <el-button v-if="scope.row.from!='default'" type="text" size="small" @click.native.prevent="editRow(scope.$index, template_data)">编辑</el-button>
              <el-button v-if="scope.row.from!='default'" type="text" size="small" @click.native.prevent="template_write(scope.$index, template_data)">内容填写</el-button>
              <el-button v-if="scope.row.from!='default'" type="text" size="small" @click.native.prevent="template_write_record(scope.$index, template_data)">填写记录</el-button>
              <el-button
                v-if="scope.row.from!='default'"
                @click.native.prevent="deleteRow(scope.$index, template_data)"
                type="text"
                class="Danger"
                size="small">
                删除
              </el-button>
              <el-button v-if="scope.row.from=='default'" type="text" size="small" @click.native.prevent="lookRow(scope.$index, template_data)">查看</el-button>
              <el-button v-if="scope.row.from=='default'" type="text" size="small" @click.native.prevent="copyRow(scope.$index, template_data)">一键复制</el-button>
            </template>
          </el-table-column>
        </el-table>
      </el-main>

      <el-footer>
        <div v-show="total_page>0" class="page_msg">
          <el-pagination
            background
            layout="prev, pager, next"
            :page-count="total_page"
            :current-page="page"
            @current-change="current_change"
          >
          </el-pagination>
        </div>
      </el-footer>
    </el-container>

    <el-dialog
      title="二维码(可右击保存供用户扫码申请)"
      :visible.sync="look_qrcodeVisible"
      :close-on-click-modal="false"
      :center="true"
      width="400px">
      <div style="width: 100%;text-align:center;">
         <el-image
          style="width: 200px; height: 200px"
          :src="look_qrcode_url"
          fit="contain">
         </el-image>
      </div>
    </el-dialog>
  </div>

</template>

<script>
  export default {
    name:'vote_list',
    data() {
      return {
        look_qrcode_url: '',
        look_qrcodeVisible: false,
        page: 1,
        total_page: 20,
        pagerCount: 10,
        date: '',
        options: [{
          value: 'template_id',
          label: '模板ID'
        }, {
          value: 'template_title',
          label: '模板标题'
        }],
        search_val: '',
        search_type: 'template_id',
        template_data: []
      }
    },
    created () {
      var _this = this
      this.getTemplateList();
    },
    methods: {
      template_write: function(index, rows) {
        let msg = rows[index];
        this.$router.replace({ path: '/template_write', query: { template_id: msg.template_id }});
      },
      template_title_write: function(index, rows) {
        let msg = rows[index];
        this.$router.replace({ path: '/template_title_write', query: { template_id: msg.template_id }});
      },
      template_write_record: function(index, rows) {
        let msg = rows[index];
        this.$router.replace({ path: '/write_list', query: { template_id: msg.template_id }});
      },
      // 请求数据
      async getTemplateList () {
        let _this = this
        let param = {
          page: this.page,
          search_val: this.search_val,
          search_type: this.search_type,
        }
        if (this.date) {
          let start_time = this.date[0];
          let end_time = this.date[1];
          param.start_time = start_time;
          param.end_time = end_time;
        }
          console.log('param',param);
        let res = await this.$api.templateList(param);
        if (!res) return;
        console.log('getTemplateList: ', res);
        this.total_page = res.total_page;
        this.template_data = res.list;
      },
      // 删除
      async delTemplate (template_id, rows, index, _this) {
        let param = {
          template_id: template_id,
        }
        let res = await this.$api.delTemplate(param);
        console.log(`删除: `, res);
        if (res) {
          rows.splice(index, 1);
          _this.$message({
            type: 'success',
            message: '删除成功!'
          });
        } else if (res.errorMsg) {
          _this.$message({
            type: 'info',
            message: res.errorMsg
          });
        }
        return res;
      },
      search_list() {
        console.log('搜索');
        console.log('search_type',this.search_type);
        console.log('search_val',this.search_val);
        this.page = 1;
        this.getTemplateList();
      },
      current_change(val) {
        this.page = val;
        this.getTemplateList();
        console.log(`当前页: ${val}`);
        console.log(`当前页1: `,this.page);
      },
      tableRowClassName({row, rowIndex}) {
        if (row['status'] === '0') {
          return 'warning_row';
        }
        return '';
      },
      deleteRow(index, rows) {
        let _this = this
        this.$confirm('此操作将永久删除该模板, 是否继续?', '提示', {
          confirmButtonText: '确定',
          cancelButtonText: '取消',
          type: 'warning'
        }).then(() => {
          let template_id = rows[index]['template_id'];
          this.delTemplate(template_id, rows, index, _this);
        }).catch(() => {
          _this.$message({
            type: 'info',
            message: '已取消删除'
          });
        });
      },
      editRow(index,rows) {
        let msg = rows[index];
        this.$router.replace({ path: '/add_template', query: { template_id: msg.template_id }});
      },
      look_qrcode(index,rows) {
        let msg = rows[index];
        console.log('look_qrcode', msg);
        this.look_qrcode_url = msg['qrcode_url'];
        this.look_qrcodeVisible = true;
      },
      lookRow(index,rows) {
        let msg = rows[index];
        console.log('lookRow', msg);
        this.$router.replace({ path: '/template_look', query: { template_id: msg.template_id }});
      },
      copyRow(index,rows) {
        let msg = rows[index];
        console.log('copyRow', msg);
        let _this = this
        this.$confirm('是否确定进行复制?', '提示', {
          confirmButtonText: '确定',
          cancelButtonText: '取消',
          type: 'warning'
        }).then(() => {
          let template_id = rows[index]['template_id'];
          this.copyTemplate(template_id, rows, index, _this);
        }).catch(() => {
          _this.$message({
            type: 'info',
            message: '已取消复制'
          });
        });
      },
      async copyTemplate(template_id, rows, index, _this) {
        let param = {
          template_id: template_id,
          from: rows[index]['from'],
        }
        let res = await this.$api.copy_template(param);
        console.log(`复制模板: `, res);
        if (res) {
          _this.$message({
            type: 'success',
            message: '成功!'
          });
          this.getTemplateList();
        } else if (res.errorMsg) {
          _this.$message({
            type: 'info',
            message: res.errorMsg
          });
        }
        return res;
      },
      add_template() {
        this.$router.replace({ path: '/add_template'});
      }
    }
  }
</script>
<style scoped>
  .vote_list_box {
    padding: 20px 10px;
  }
  .vote_list_box .list_table {
    border: 1px solid #EBEEF5;
  }
  .vote_list_box .table_box {
    width: 100%;
  }
  .vote_list_box .Danger {
    color: #F56C6C;
  }
  .vote_list_box .search_width {
    width: 150px;
  }
  .vote_list_box .page_msg {
    text-align: center;
  }
</style>
